// The actor has no 'new only' mode: keep listings first listed in the last N days.
const DAYS = 7;
const cutoff = Date.now() - DAYS * 24 * 3600 * 1000;
const today = new Date().toISOString().slice(0, 10);
const out = [];
for (const { json: r } of $input.all()) {
  if (!r.listedAt || Date.parse(r.listedAt) < cutoff) continue;
  out.push({ json: {
    runDate: today,
    listedAt: String(r.listedAt).slice(0, 10),
    title: r.title,
    price: r.price,
    currency: r.currency,
    propertyType: r.propertyType,
    bedrooms: r.bedrooms,
    bathrooms: r.bathrooms,
    sizeSqft: r.sizeSqft,
    community: r.community,
    building: r.building,
    furnishing: r.furnishing,
    completionStatus: r.completionStatus,
    brokerName: r.brokerName,
    listingId: r.listingId,
    url: r.url,
  }});
}
out.sort((a, b) => (a.price ?? 0) - (b.price ?? 0));
return out;
